DROP TABLE IF EXISTS `analytics_purchase_events`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `analytics_purchase_events` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `client_id` bigint unsigned NOT NULL,
  `integration_id` bigint unsigned NOT NULL,
  `source` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ga4',
  `transaction_id` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `event_date` date NOT NULL,
  `event_timestamp` datetime NOT NULL,
  `tracked_revenue` decimal(15,2) NOT NULL DEFAULT '0.00',
  `currency` varchar(3) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'USD',
  `user_pseudo_id` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_duplicate` tinyint(1) NOT NULL DEFAULT '0',
  `duplicate_reason` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_updated_at` datetime DEFAULT NULL,
  `collected_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `metadata_json` json DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_analytics_tx_unique` (`client_id`,`integration_id`,`source`,`transaction_id`),
  KEY `analytics_purchase_events_integration_id_foreign` (`integration_id`),
  KEY `idx_analytics_client_date` (`client_id`,`event_date`),
  CONSTRAINT `analytics_purchase_events_client_id_foreign` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`) ON DELETE CASCADE,
  CONSTRAINT `analytics_purchase_events_integration_id_foreign` FOREIGN KEY (`integration_id`) REFERENCES `integrations` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=12168 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
