DROP TABLE IF EXISTS `commerce_metrics`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `commerce_metrics` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `client_id` bigint unsigned NOT NULL,
  `date` date NOT NULL,
  `source` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'adobe_commerce',
  `revenue` decimal(15,2) DEFAULT NULL,
  `orders` int unsigned DEFAULT NULL,
  `items_sold` int NOT NULL DEFAULT '0',
  `conversion_rate` decimal(8,4) DEFAULT NULL,
  `average_order_value` decimal(10,2) DEFAULT NULL,
  `aov` decimal(12,2) NOT NULL DEFAULT '0.00',
  `sessions` int unsigned DEFAULT NULL,
  `active_users` int unsigned NOT NULL DEFAULT '0',
  `new_customers` int unsigned DEFAULT NULL,
  `returning_customers` int unsigned DEFAULT NULL,
  `source_breakdown_json` json DEFAULT NULL,
  `device_breakdown_json` json DEFAULT NULL,
  `metadata_json` json DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `commerce_metrics_client_date_source_unique` (`client_id`,`date`,`source`),
  KEY `commerce_metrics_date_index` (`date`),
  CONSTRAINT `commerce_metrics_client_id_foreign` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3158 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
