--
-- Table structure for table `commerce_orders`
--

DROP TABLE IF EXISTS `commerce_orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `commerce_orders` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `client_id` bigint unsigned NOT NULL,
  `integration_id` bigint unsigned NOT NULL,
  `source` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'adobe_commerce',
  `source_order_id` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_increment_id` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `order_status` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'processing',
  `customer_identity_hash` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `registered_customer_id` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `order_date` datetime NOT NULL,
  `refund_date` datetime DEFAULT NULL,
  `gross_revenue` decimal(15,2) NOT NULL DEFAULT '0.00',
  `refunded_revenue` decimal(15,2) NOT NULL DEFAULT '0.00',
  `net_revenue` decimal(15,2) NOT NULL DEFAULT '0.00',
  `tax_amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `shipping_amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `discount_amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `currency` varchar(3) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'USD',
  `base_currency` varchar(3) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'USD',
  `reporting_currency` varchar(3) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'USD',
  `exchange_rate` decimal(12,6) NOT NULL DEFAULT '1.000000',
  `is_valid` tinyint(1) NOT NULL DEFAULT '1',
  `exclusion_reason` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
