CREATE TABLE `meeting_preps` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `client_meeting_id` bigint unsigned NOT NULL,
  `jira_project_key` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `jira_jql` text COLLATE utf8mb4_unicode_ci,
  `internal_summary` longtext COLLATE utf8mb4_unicode_ci,
  `generated_status_email_subject` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `generated_status_email_body` longtext COLLATE utf8mb4_unicode_ci,
  `edited_status_email_subject` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `edited_status_email_body` longtext COLLATE utf8mb4_unicode_ci,
  `recommended_agenda` json DEFAULT NULL,
  `jira_snapshot` json DEFAULT NULL,
  `gmail_draft_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `email_sent_at` timestamp NULL DEFAULT NULL,
  `email_to` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `email_cc` json DEFAULT NULL,
  `google_doc_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `google_doc_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ai_provider` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ai_model` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ai_error` text COLLATE utf8mb4_unicode_ci,
  `generated_at` timestamp NULL DEFAULT NULL,
  `approved_at` timestamp NULL DEFAULT NULL,
  `approved_by` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `meeting_preps_client_meeting_id_foreign` (`client_meeting_id`),
  KEY `meeting_preps_approved_by_foreign` (`approved_by`),
  CONSTRAINT `meeting_preps_approved_by_foreign` FOREIGN KEY (`approved_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `meeting_preps_client_meeting_id_foreign` FOREIGN KEY (`client_meeting_id`) REFERENCES `client_meetings` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
